    @Override
    public BigDecimal frete(Pedido pedido) {
        return Dinheiro.centavos(BASE.add(POR_KG.multiply(pedido.pesoKg())));
    }

    @Override
    public int prazoEntregaDias() {
        return 7;
    }
}
